<script lang="ts">
 import type {Snippet} from 'svelte';
 import type {Dashboard,Contribution,Template,Document} from './types';
 let {email,summary,contributions,templates,documents,loading,onview,onpreview,onopen,onwithdraw,oncheck,contributionsOnly=false,member}:{email:string;summary:Dashboard|null;contributions:Contribution[];templates:Template[];documents:Document[];loading:boolean;onview:(view:'templates'|'sources'|'documents'|'contributions')=>void;onpreview:(t:Template)=>void;onopen:(id:string)=>void;onwithdraw:(id:string)=>void;oncheck:(id:string)=>void;contributionsOnly?:boolean;member?:Snippet}=$props();
 const status={pending:'Awaiting review',approved:'Public',rejected:'Rejected',withdrawn:'Withdrawn'};
</script>
<main class="mypage">
 <div class="welcome"><div><span class="eyebrow">{contributionsOnly?'SHARE A BETTER START':'MY DOCUMENT MEMORY'}</span><h1>{contributionsOnly?'My contributions':'My page'}<span>.</span></h1><p>{contributionsOnly?'Follow the templates you have shared.':'Good starting points make your next document.'}</p></div><div class="account"><span>Your account</span><strong>{email}</strong><small>Your references and documents are private.</small></div></div>
