   <button onclick={()=>onview(card.key as 'templates'|'sources'|'documents'|'contributions')}><span>{card.label} <b>↗</b></span><strong>{summary?summary[card.key as keyof Dashboard]:'—'}</strong><small>{card.sub}</small></button>
  {/each}
 </section>
 <div class="memory-grid"><section class="memory-box"><div class="section-heading"><h2>My memories</h2><button class="text-button" onclick={()=>onview('templates')}>View all →</button></div><p class="muted">Start your next task from your templates.</p>{#each templates.filter(t=>t.visibility==='private').slice(0,4) as t}<button class="memory-row" onclick={()=>onpreview(t)}><span class="memory-icon">▤</span><span><strong>{t.title}</strong><small>v{t.version} · Private template</small></span><b>↗</b></button>{:else}<div class="empty-card"><p>You have no saved templates yet.</p><button class="secondary" onclick={()=>onview('templates')}>Choose your first template →</button></div>{/each}</section>
 <section class="memory-box"><div class="section-heading"><h2>Recent documents</h2><button class="text-button" onclick={()=>onview('documents')}>View all →</button></div><p class="muted">Continue from your last saved version.</p>{#each documents.slice(0,4) as d}<button class="memory-row" onclick={()=>onopen(d.id)}><span class="memory-icon">▱</span><span><strong>{d.title}</strong><small>{d.family==='deck'?'Slides':'Document'} · v{d.version}</small></span><b>↗</b></button>{:else}<div class="empty-card"><p>Your documents will appear here.</p><button class="secondary" onclick={()=>onview('templates')}>Start from a template →</button></div>{/each}</section></div>
 {/if}
 <section class="memory-box contributions"><div class="section-heading"><div><span class="eyebrow">MY CONTRIBUTIONS</span><h2>Templates you have shared</h2></div><button class="secondary" onclick={()=>onview('templates')}>Contribute a template +</button></div><p class="muted">Preview and submit your template structure for review. Your reference files and document content stay private.</p>
 {#each contributions as c}<article class="contribution"><div><span class:approved={c.status==='approved'} class="state">{status[c.status]}</span><h3>{c.snapshot.title}</h3><p>{c.snapshot.author} · {c.snapshot.license} · v{c.snapshot.version}</p></div><div class="contribution-actions"><button class="text-button" disabled={loading} onclick={()=>oncheck(c.id)}>View review checks</button>{#if c.status==='pending'||c.status==='approved'}<button class="text-button" disabled={loading} onclick={()=>onwithdraw(c.id)}>Withdraw contribution</button>{/if}</div></article>{:else}<div class="empty-card"><h3>Good structures become more useful when shared.</h3><p>Share a reusable structure after removing personal content.</p></div>{/each}
 </section>
</main>
